create or replace package body order_status_api as
  procedure set_status(p_order_id in number, p_status in varchar2) is
    v_old_status shop_orders.status%TYPE;
  begin
    -- Get the current status before updating
    select status into v_old_status from shop_orders where order_id = p_order_id;

    -- Update the status
    update shop_orders set status = upper(p_status) where order_id = p_order_id;

    -- Log the status change if it is different from the old status
    if upper(p_status) <> v_old_status then
      insert into order_status_log (order_id, old_status, new_status, log_date)
      values (p_order_id, v_old_status, upper(p_status), SYSDATE);
    end if;
  end set_status;

  function last_change(p_order_id in number) return varchar2 is
    l_change varchar2(25);
  begin
    select old_status || '->' || new_status
      into l_change
      from order_status_log
     where order_id = p_order_id
     order by log_id desc
     fetch first 1 row only;
    return l_change;
  exception
    when no_data_found then
      return null;
  end last_change;
end order_status_api;
/

